create temporary table tc_access_qa(result jsonb);
do $$
declare co uuid:=gen_random_uuid();otherco uuid:=gen_random_uuid();p1 uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();p3 uuid:=gen_random_uuid();admin_ uuid:=gen_random_uuid();pm uuid:=gen_random_uuid();owner_ uuid:=gen_random_uuid();otheradmin uuid:=gen_random_uuid();newuser uuid:=gen_random_uuid();plan_ uuid;rid uuid;settings jsonb;rows_ jsonb;c integer;checks integer:=0;denied boolean;
begin
 begin
 insert into auth.users(id,email) select x,x::text||'@qa.invalid' from unnest(array[admin_,pm,owner_,otheradmin]) x;
 insert into public.profiles(id,role,active) values(admin_,'admin',true),(pm,'pm',true),(owner_,'owner',true),(otheradmin,'admin',true) on conflict(id) do update set role=excluded.role,active=true;
 insert into public.companies(id,name) values(co,'Transient user access QA'),(otherco,'Other transient access QA');
 insert into public.company_users(company_id,user_id,active) values(co,admin_,true),(co,pm,true),(co,owner_,true),(otherco,otheradmin,true);
 insert into public.projects(id,company_id,name) values(p1,co,'Project One'),(p2,co,'Project Two'),(p3,otherco,'Other company project');
 insert into public.project_members(project_id,user_id,role,active) values(p1,pm,'pm',true),(p2,pm,'pm',true),(p1,owner_,'owner',true);
 insert into public.rfis(project_id,rfi_no,subject,question,created_by) values(p1,'RFI-001','Question','Details',pm) returning id into rid;
 insert into public.tc_project_messages(project_id,sender_id,subject,body,channel) values(p1,pm,'QA message','QA body','project');
 insert into public.tc_project_events(project_id,created_by,title,event_type,starts_at,ends_at) values(p1,pm,'QA event','meeting',now(),now()+interval '1 hour');
 perform set_config('request.jwt.claim.sub',admin_::text,true);execute 'set local role authenticated';
 rows_:=public.tc_access_roster(co);if jsonb_array_length(rows_->'users')<>3 or jsonb_array_length(rows_->'projects')<>2 then raise exception 'Roster not company scoped';end if;checks:=checks+1;
 settings:=jsonb_build_array(jsonb_build_object('projectId',p1,'role','pm','allow',jsonb_build_array('drawings'),'deny',jsonb_build_array('rfi','financial_project','internal','external','meetings')),jsonb_build_object('projectId',p2,'role','superintendent','allow','[]'::jsonb,'deny','[]'::jsonb));
 perform public.tc_access_save(co,pm,0,settings);checks:=checks+1;
 denied:=false;begin perform public.tc_access_save(co,pm,0,settings);exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Stale editor overwrote permissions';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_access_save(co,admin_,0,'[]');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Administrator self lockout allowed';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_access_save(co,pm,1,jsonb_build_array(jsonb_build_object('projectId',p3,'role','pm','allow','[]'::jsonb,'deny','[]'::jsonb)));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Other company assignment accepted';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',pm::text,true);
 if tc_access_private.has_permission(p1,'rfi') or not tc_access_private.has_permission(p2,'rfi') then raise exception 'Deny leaked across projects or failed';end if;checks:=checks+1;
 select count(*) into c from public.rfis where id=rid;if c<>0 then raise exception 'Denied RFI still readable through REST policies';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_detail('rfi',rid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Denied RFI RPC bypass';end if;checks:=checks+1;
 select count(*) into c from public.tc_project_messages where project_id=p1;if c<>0 then raise exception 'Denied collaboration still visible';end if;checks:=checks+1;
 select count(*) into c from public.tc_project_events where project_id=p1;if c<>0 then raise exception 'Denied meeting events still visible';end if;checks:=checks+1;
 if tc_import_private.can_access(p1,'budget') then raise exception 'Denied budget RPC access';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_access_roster(co);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Nonadmin accessed roster';end if;checks:=checks+1;
 denied:=false;begin update public.project_members set role='admin' where user_id=pm;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Direct membership privilege escalation';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',otheradmin::text,true);
 denied:=false;begin perform public.tc_access_roster(co);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Other company admin accessed roster';end if;checks:=checks+1;
 select count(*) into c from public.projects where company_id=co;if c<>0 then raise exception 'Other company project list leaked';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',admin_::text,true);
 perform public.tc_access_save(co,owner_,0,jsonb_build_array(jsonb_build_object('projectId',p1,'role','owner','allow',jsonb_build_array('financial_project'),'deny','[]'::jsonb)));
 perform set_config('request.jwt.claim.sub',owner_::text,true);
 if not tc_import_private.can_access(p1,'budget') or tc_import_private.can_access(p2,'budget') then raise exception 'Additional grant incorrectly scoped';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',admin_::text,true);perform public.tc_access_save(co,owner_,1,'[]');
 perform set_config('request.jwt.claim.sub',owner_::text,true);if tc_access_private.has_permission(p1,'project') or tc_import_private.can_access(p1,'budget') then raise exception 'Removed project still available';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',admin_::text,true);
 plan_:=public.tc_access_prepare_invite(co,newuser::text||'@qa.invalid','New QA employee','pm',settings);checks:=checks+1;
 execute 'set local role postgres';
 insert into auth.users(id,email,raw_user_meta_data) values(newuser,newuser::text||'@qa.invalid',jsonb_build_object('access_plan_id',plan_));
 if not exists(select 1 from public.project_members where user_id=newuser and project_id=p1 and role='pm' and active) or not exists(select 1 from public.project_members where user_id=newuser and project_id=p2 and role='superintendent' and active) then raise exception 'Invite did not establish all projects before delivery';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',newuser::text,true);
 if tc_access_private.has_permission(p1,'rfi') or not tc_access_private.has_permission(p2,'rfi') then raise exception 'Invite lost permission restrictions';end if;checks:=checks+1;
 if not exists(select 1 from public.tc_user_access_events where user_id=newuser and actor_id=admin_) then raise exception 'Invite audit missing';end if;checks:=checks+1;
 denied:=false;begin insert into auth.users(id,email,raw_user_meta_data) values(gen_random_uuid(),'spoof@qa.invalid',jsonb_build_object('access_plan_id',plan_));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Consumed plan reused for another identity';end if;checks:=checks+1;
 raise exception using errcode='ZQ005',message='Rollback all access fixtures';
 exception when sqlstate 'ZQ005' then null;
 end;
 if exists(select 1 from auth.users where id=admin_) then raise exception 'Fixtures persisted';end if;
 insert into tc_access_qa values(jsonb_build_object('status','PASS','checks',checks,'fixtures_rolled_back',true,'email_sent',false));
end $$;
select result from tc_access_qa;
